<script>
(function($){
 const API='risk_dashboard_api.php',CSRF=<?php echo json_encode($csrf); ?>;
 let cache=null,currentStudent=null,filterOptions={levels:[],grades:{},sections:{}};
 const esc=v=>$('<div>').text(v==null?'':v).html();
 const pct=v=>(Number(v||0)*100).toFixed(1)+'%';
 const statusClass=s=>'risk-status-'+String(s||'').replace(/\s+/g,'');
 const gradeLabel=v=>String(v||'').replace(/°+$/,'')+'°';
 function selected(selector){return String($(selector).val()||'').trim()}
 function params(){const q=new URLSearchParams({action:'dashboard'});[['search','#risk-search'],['level','#risk-level'],['grade','#risk-grade'],['section','#risk-section'],['risk_level','#risk-risk-level'],['bimestre','#risk-bimester'],['intervention_status','#risk-intervention-status']].forEach(([k,s])=>{let v=selected(s);if(v)q.set(k,v)});return q.toString()}
 function notice(text,type='warning'){$('#risk-alert').html('<div class="alert alert-'+type+'">'+esc(text)+'</div>')}
 function card(label,value,tone,icon,help){return '<div class="col-xl-3 col-md-6 mb-3"><div class="risk-card"><div class="d-flex justify-content-between"><div><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong>'+(help?'<div class="risk-note">'+esc(help)+'</div>':'')+'</div><span class="risk-icon risk-'+tone+'"><i class="fas '+icon+'"></i></span></div></div></div>'}
 function factorText(f){if(!f)return '';let raw=Number(f.value||0),v=f.feature==='attendance_rate_30d'?raw.toFixed(1)+'%':(['grade_mean_current','grade_trend'].includes(f.feature)?raw.toFixed(2):raw.toFixed(0));return esc(f.label||f.feature)+': '+v}
 function setOptions($select,items,emptyLabel,formatter){let current=String($select.val()||'');let html='<option value="">'+esc(emptyLabel)+'</option>';items.forEach(v=>html+='<option value="'+esc(v)+'">'+esc(formatter?formatter(v):v)+'</option>');$select.html(html);if(items.map(String).includes(current))$select.val(current)}
 function syncGradeOptions(){let level=selected('#risk-level'),items=level?(filterOptions.grades?.[level]||[]):Object.values(filterOptions.grades||{}).flat();items=[...new Set(items.map(Number).filter(Boolean))].sort((a,b)=>a-b);setOptions($('#risk-grade'),items,'Todos',gradeLabel);syncSectionOptions()}
 function syncSectionOptions(){let level=selected('#risk-level'),grade=selected('#risk-grade'),items=[];if(level&&grade)items=filterOptions.sections?.[level+'|'+grade]||[];else{Object.entries(filterOptions.sections||{}).forEach(([key,vals])=>{let parts=key.split('|');if((!level||parts[0]===level)&&(!grade||parts[1]===grade))items.push(...vals)})}items=[...new Set(items)].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true}));setOptions($('#risk-section'),items,'Todas')}
 function hydrateFilters(d){filterOptions=d.filters||filterOptions;let currentLevel=selected('#risk-level');setOptions($('#risk-level'),filterOptions.levels||[],'Todos');if(currentLevel&&(filterOptions.levels||[]).includes(currentLevel))$('#risk-level').val(currentLevel);syncGradeOptions();renderActiveFilters()}
 function renderActiveFilters(){let labels=[];let map=[['#risk-search','Estudiante'],['#risk-level','Nivel'],['#risk-grade','Grado'],['#risk-section','Sección'],['#risk-risk-level','Alerta'],['#risk-bimester','Bimestre'],['#risk-intervention-status','Intervención']];map.forEach(([s,label])=>{let v=selected(s);if(v)labels.push('<span class="risk-filter-badge">'+esc(label)+': '+esc(s==='#risk-grade'?gradeLabel(v):$(s).find('option:selected').text()||v)+'</span>')});$('#risk-active-filters').html(labels.join(''))}
 function renderContext(d){let p=d.period||{},t=d.model?.thresholds||{medium:.4,high:.7};$('#risk-context-base').text(p.base?p.base+' bimestre cerrado':'Último bimestre cerrado');$('#risk-context-cutoff').text(p.cutoff?'Fecha de corte: '+p.cutoff:'Solo datos disponibles hasta su cierre.');$('#risk-context-target').text(p.target?'Riesgo estimado en el '+p.target+' bimestre':'Riesgo del bimestre siguiente');$('#risk-context-thresholds').text('Bajo < '+(Number(t.medium)*100).toFixed(0)+'% · Medio '+(Number(t.medium)*100).toFixed(0)+'–'+(Number(t.high)*100-0.1).toFixed(1)+'% · Alto ≥ '+(Number(t.high)*100).toFixed(0)+'%')}
 async function load(){ $('#risk-loading').removeClass('d-none');$('#risk-content').addClass('d-none');$('#risk-alert').empty();try{let r=await fetch(API+'?'+params(),{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo cargar el panel.');cache=d;hydrateFilters(d);render(d)}catch(e){notice(e.message,'danger')}finally{$('#risk-loading').addClass('d-none')}}
 function render(d){$('#risk-content').removeClass('d-none');renderContext(d);if(!d.model.available)notice('El modelo predictivo activo no está disponible. Revisa el entrenamiento antes de interpretar alertas.','warning');else if(!d.migration_ready)notice('Las alertas funcionan, pero falta ejecutar sql/predictive_interventions_upgrade.sql para registrar intervenciones.','warning');
 let s=d.summary||{};$('#risk-cards').html(card('Alerta alta',s.high||0,'danger','fa-exclamation-triangle','Prioridad de revisión')+card('Alerta media',s.medium||0,'warning','fa-exclamation-circle','Requiere seguimiento')+card('Alerta baja',s.low||0,'success','fa-check-circle','Mantener observación')+card('Estudiantes evaluados',s.evaluated||0,'primary','fa-users',s.attendance_missing?String(s.attendance_missing)+' sin asistencia suficiente':'Con los filtros actuales'));
 let rows='';(d.predictions||[]).forEach(x=>{let st=x.student,f=(x.factors||[]).map(factorText).join('<br>'),base=x.bimester_label||x.bimester,target=x.target_bimester_label||x.target_bimester,dt=x.details||{};let data=[];if(dt.grade_mean_current!=null)data.push('Prom. '+Number(dt.grade_mean_current).toFixed(2));if(dt.critical_courses_current!=null)data.push('Cursos críticos '+Number(dt.critical_courses_current).toFixed(0));if(x.attendance_available&&dt.attendance_rate_30d!=null)data.push('Asist. '+Number(dt.attendance_rate_30d).toFixed(1)+'%');else data.push('Asistencia sin datos');rows+='<tr><td><strong>'+esc(st.name)+'</strong><div class="text-muted small">'+esc(base)+' cerrado → '+esc(target)+(x.base_closed_at?' · '+esc(x.base_closed_at):'')+'</div></td><td>'+esc(st.nivel)+'<br>'+esc(gradeLabel(st.grado))+' '+esc(st.seccion)+'</td><td><span class="risk-badge risk-badge-'+esc(x.level)+'">'+esc(x.level)+' · '+pct(x.probability)+'</span>'+(x.open_interventions?'<div class="small text-muted mt-1">'+esc(x.open_interventions)+' intervención(es) abierta(s)</div>':'')+'</td><td class="risk-factor">'+(f||'Sin factor dominante')+'</td><td class="risk-data-line">'+data.map(esc).join('<br>')+'</td><td class="text-right risk-actions"><button class="btn btn-sm btn-outline-secondary risk-detail" data-id="'+st.id+'" title="Ver detalle"><i class="fas fa-eye mr-1"></i>Detalle</button><button class="btn btn-sm btn-outline-primary risk-sim" data-id="'+st.id+'" title="Simular mejora"><i class="fas fa-project-diagram"></i></button><button class="btn btn-sm btn-primary risk-new" data-id="'+st.id+'" title="Registrar intervención"><i class="fas fa-hands-helping"></i></button></td></tr>'});$('#risk-students').html(rows||'<tr><td colspan="6" class="risk-empty"><i class="fas fa-search fa-2x mb-2 d-block"></i>No hay alertas disponibles con estos filtros. Verifica el bimestre seleccionado o limpia los filtros.</td></tr>');$('#risk-list-count').text((d.predictions||[]).length+' resultado(s) mostrado(s)');
 let factors=d.factors||[],max=Math.max(...factors.map(x=>Number(x.count||0)),1),fh='';factors.forEach(x=>fh+='<div class="risk-bar-row"><span>'+esc(x.label)+'</span><div class="risk-track"><div class="risk-fill" style="width:'+(Number(x.count||0)/max*100)+'%"></div></div><strong>'+esc(x.count)+'</strong></div>');$('#risk-factors').html(fh||'<div class="risk-empty">Sin factores agregados para esta selección.</div>');
 renderInterventions(d.interventions||[],d.intervention_summary||{});let e=d.effectiveness||{};$('#risk-effectiveness').html('<div class="row"><div class="col-6 mb-2"><div class="risk-modal-kpi"><small>Medidas</small><strong>'+esc(e.measured||0)+'</strong></div></div><div class="col-6 mb-2"><div class="risk-modal-kpi"><small>Con menor riesgo</small><strong>'+esc(e.improved||0)+'</strong></div></div></div>'+(e.average_probability_reduction!=null?'<div class="risk-muted-box mt-2"><strong>Reducción media observada:</strong> '+(Number(e.average_probability_reduction)*100).toFixed(1)+' puntos porcentuales.<div class="risk-note mt-1">Comparación antes/después; no demuestra causalidad.</div></div>':'<div class="risk-empty">Aparecerán resultados cuando exista un nuevo bimestre cerrado después de las intervenciones.</div>'));let variant=d.model?.schema_version?'v'+d.model.schema_version:'modelo activo';$('.risk-model-line').remove();$('.risk-hero .risk-sub').after('<div class="risk-model-line"><span class="risk-experimental">Modelo activo '+esc(variant)+'</span> · Las variantes experimentales no modifican este panel hasta ser validadas.</div>')}
 function renderInterventions(rows,sum){let html='';rows.forEach(r=>html+='<tr><td><strong>'+esc(r.student_name)+'</strong><div class="small text-muted">'+esc(r.nivel)+' · '+esc(gradeLabel(r.grado))+' '+esc(r.seccion)+'</div></td><td>'+esc(r.intervention_type)+'<div class="small text-muted">'+esc(r.title)+'</div></td><td><span class="risk-badge '+statusClass(r.status)+'">'+esc(r.status)+'</span>'+(r.status==='Completada'&&r.post_risk_probability==null?'<div class="small text-muted mt-1">Medición posterior pendiente</div>':'')+'</td><td>'+esc(r.followup_date||'—')+'</td><td>'+(r.risk_probability!=null?pct(r.risk_probability):'—')+'</td><td class="text-right"><button class="btn btn-sm btn-outline-secondary risk-edit" data-id="'+r.id+'"><i class="fas fa-edit mr-1"></i>Actualizar</button></td></tr>');$('#risk-interventions').html(html||'<tr><td colspan="6" class="risk-empty">No hay intervenciones con los filtros actuales.</td></tr>');$('#risk-intervention-kpis').text('Pendientes: '+(sum['Pendiente']||0)+' · En proceso: '+(sum['En proceso']||0)+' · Vencidas: '+(sum['Seguimientos vencidos']||0))}
 function findPrediction(id){return (cache?.predictions||[]).find(x=>Number(x.student.id)===Number(id))}
 async function studentDetail(id){let url=API+'?action=student&student_id='+encodeURIComponent(id),b=selected('#risk-bimester');if(b)url+='&bimestre='+encodeURIComponent(b);let r=await fetch(url,{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo consultar al estudiante.');return d}
 function renderFactorList(items){if(!items||!items.length)return '<div class="text-muted small">No hay un factor individual dominante.</div>';return '<ul class="risk-detail-list">'+items.map(f=>'<li><i class="fas fa-angle-right text-primary mr-1"></i>'+factorText(f)+'</li>').join('')+'</ul>'}
 $(document).on('click','.risk-detail',async function(){try{let d=await studentDetail($(this).data('id')),p=d.prediction,st=d.student;if(!p.available)throw new Error('No existe una predicción disponible para el bimestre seleccionado.');currentStudent=st;let f=p.features||{},courses=f._critical_course_names||[],att=p.data_quality?.attendance_available;$('#risk-detail-subtitle').text(st.name+' · '+st.nivel+' · '+gradeLabel(st.grado)+' '+st.seccion);let h='<div class="row mb-3"><div class="col-md-4 mb-2"><div class="risk-modal-kpi"><small>Alerta estimada</small><strong><span class="risk-badge risk-badge-'+esc(p.level)+'">'+esc(p.level)+' · '+pct(p.probability)+'</span></strong></div></div><div class="col-md-4 mb-2"><div class="risk-modal-kpi"><small>Información base</small><strong>'+esc(p.bimester_label||p.bimester)+' bimestre</strong></div></div><div class="col-md-4 mb-2"><div class="risk-modal-kpi"><small>Bimestre estimado</small><strong>'+esc(p.target_bimester_label||p.target_bimester)+' bimestre</strong></div></div></div>';h+='<div class="row"><div class="col-md-6"><div class="risk-section-title">Datos académicos utilizados</div><ul class="risk-detail-list"><li><strong>Promedio actual:</strong> '+(f.grade_mean_current!=null?Number(f.grade_mean_current).toFixed(2):'Sin dato')+'</li><li><strong>Tendencia respecto al bimestre anterior:</strong> '+(Number(f.previous_bimester_available||0)>=.5?(Number(f.grade_trend||0)>=0?'+':'')+Number(f.grade_trend||0).toFixed(2)+' puntos':'Sin bimestre previo comparable')+'</li><li><strong>Registros críticos:</strong> '+Number(f.critical_records_current||0).toFixed(0)+'</li><li><strong>Cursos críticos:</strong> '+Number(f.critical_courses_current||0).toFixed(0)+(courses.length?' · '+esc(courses.join(', ')):'')+'</li></ul></div><div class="col-md-6"><div class="risk-section-title">Asistencia previa al cierre</div><ul class="risk-detail-list">'+(att?'<li><strong>Asistencia:</strong> '+Number(f.attendance_rate_30d||0).toFixed(1)+'%</li><li><strong>Días de tardanza:</strong> '+Number(f.late_30d||0).toFixed(0)+'</li><li><strong>Días de ausencia:</strong> '+Number(f.absent_30d||0).toFixed(0)+'</li>':'<li>Sin registros suficientes de asistencia. El modelo trató esos valores como faltantes.</li>')+'</ul></div></div>';h+='<div class="row mt-3"><div class="col-md-6"><div class="risk-section-title">Factores que elevan la alerta</div>'+renderFactorList(p.explanation?.raises||[])+'</div><div class="col-md-6"><div class="risk-section-title">Factores que reducen la alerta</div>'+renderFactorList(p.explanation?.reduces||[])+'</div></div><div class="risk-help mt-3"><i class="fas fa-info-circle text-primary mr-1"></i>Estos datos explican la estimación del modelo. No significan que una sola variable sea la causa del resultado.</div>';$('#risk-detail-body').html(h);$('#riskDetailModal').modal('show')}catch(e){notice(e.message,'danger')}});
 $(document).on('click','.risk-sim',async function(){try{let d=await studentDetail($(this).data('id'));currentStudent=d.student;let cf=d.counterfactual,p=d.prediction;if(!cf.available){$('#risk-scenario-body').html('<div class="alert alert-warning">No hay información suficiente o no existe un bimestre cerrado válido para simular cambios.</div>')}else{let rec=cf.recommended,base=p.bimester_label||p.bimester,target=p.target_bimester_label||p.target_bimester,h='<div class="alert alert-light border"><strong>Base:</strong> '+esc(base)+' bimestre cerrado'+(p.base_closed_at?' ('+esc(p.base_closed_at)+')':'')+' · <strong>Objetivo:</strong> '+esc(target)+' bimestre.</div><div class="row mb-3"><div class="col-6"><div class="risk-modal-kpi"><small>Riesgo actual</small><strong>'+esc(p.level)+' · '+pct(p.probability)+'</strong></div></div><div class="col-6"><div class="risk-modal-kpi"><small>Escenario simulado</small><strong>'+(rec?esc(rec.level)+' · '+pct(rec.probability):'Ya es bajo')+'</strong></div></div></div>';if(rec){h+='<h6 class="font-weight-bold">'+esc(rec.name)+'</h6>';rec.changes.forEach(c=>h+='<div class="risk-change"><strong>'+esc(c.label)+'</strong>: '+(c.feature==='attendance_rate_30d'?Number(c.before).toFixed(1)+'%':Number(c.before).toFixed(1))+' → '+(c.feature==='attendance_rate_30d'?Number(c.after).toFixed(1)+'%':Number(c.after).toFixed(1))+'</div>')}h+='<div class="risk-help mt-3"><i class="fas fa-info-circle text-primary mr-1"></i>Es una simulación del modelo. No garantiza que una intervención produzca exactamente este cambio.</div>';$('#risk-scenario-body').html(h)}$('#riskScenarioModal').modal('show')}catch(e){notice(e.message,'danger')}});
 function openNew(id){let x=findPrediction(id);if(!x&&currentStudent&&Number(currentStudent.id)===Number(id)){x={student:currentStudent,level:'',probability:0,suggested:null}}if(!x)return;currentStudent=x.student;$('#risk-int-student').val(x.student.id);$('#risk-int-student-label').html('<strong>'+esc(x.student.name)+'</strong><br><small>'+esc(x.student.nivel)+' · '+esc(gradeLabel(x.student.grado))+' '+esc(x.student.seccion)+(x.level?' · alerta '+esc(x.level)+' '+pct(x.probability):'')+'</small>');$('#risk-int-type').val(x.suggested?.type||'Seguimiento tutorial');$('#risk-int-title').val(x.suggested?.title||'Seguimiento preventivo de riesgo académico');$('#riskInterventionModal').modal('show')}
 $(document).on('click','.risk-new',function(){openNew($(this).data('id'))});$('#risk-scenario-intervene,#risk-detail-intervene').on('click',function(){if(currentStudent){$('#riskScenarioModal,#riskDetailModal').modal('hide');openNew(currentStudent.id)}});
 $('#risk-intervention-form').on('submit',async function(e){e.preventDefault();let fd=new FormData(this);fd.set('action','create_intervention');fd.set('csrf_token',CSRF);try{let r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo guardar.');$('#riskInterventionModal').modal('hide');notice(d.message,'success');this.reset();load()}catch(err){notice(err.message,'danger')}});
 $(document).on('click','.risk-edit',function(){let id=Number($(this).data('id')),r=(cache?.interventions||[]).find(x=>Number(x.id)===id);if(!r)return;$('#risk-up-id').val(r.id);$('#risk-up-label').html('<strong>'+esc(r.student_name)+'</strong><br><small>'+esc(r.intervention_type)+' · '+esc(r.title)+'</small>');$('#risk-up-status').val(r.status);$('#risk-up-outcome').val(r.outcome||'');$('#risk-up-followup').val(r.followup_date||'');$('#risk-up-notes').val(r.notes||'');$('#riskUpdateModal').modal('show')});
 $('#risk-update-form').on('submit',async function(e){e.preventDefault();let fd=new FormData(this);fd.set('action','update_intervention');fd.set('csrf_token',CSRF);try{let r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo actualizar.');$('#riskUpdateModal').modal('hide');notice(d.message,'success');load()}catch(err){notice(err.message,'danger')}});
 $('#risk-level').on('change',function(){syncGradeOptions();renderActiveFilters()});$('#risk-grade').on('change',function(){syncSectionOptions();renderActiveFilters()});$('#risk-section,#risk-risk-level,#risk-bimester,#risk-intervention-status').on('change',renderActiveFilters);$('#risk-search').on('input',renderActiveFilters).on('keydown',function(e){if(e.key==='Enter'){e.preventDefault();load()}});$('#risk-search-clear').on('click',function(){$('#risk-search').val('');renderActiveFilters()});
 $('#risk-clear').on('click',function(){$('#risk-search,#risk-level,#risk-grade,#risk-section,#risk-risk-level,#risk-bimester,#risk-intervention-status').val('');syncGradeOptions();renderActiveFilters();load()});$('#risk-refresh,#risk-apply').on('click',load);load();
})(jQuery);
</script>
